<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>WastedToken Mint — Challenge Coins</title>
<style>
  :root {
    --bg: #0a0b0e;
    --bg2: #12141a;
    --ink: #e8e4d9;
    --muted: #8a8678;
    --accent: #c4a35a;
    --accent-dim: #8a7340;
    --line: #2a2d36;
    --bronze: #b87333;
    --silver: #c0c6ce;
    --gold: #d4af37;
    --obsidian: #1a1a1e;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  html { scroll-behavior: smooth; }
  body {
    font-family: Georgia, "Times New Roman", serif;
    background: var(--bg);
    color: var(--ink);
    line-height: 1.55;
    min-height: 100vh;
  }
  .noise {
    pointer-events: none;
    position: fixed;
    inset: 0;
    opacity: 0.04;
    z-index: 1000;
    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  }
  header {
    position: relative;
    padding: 2.5rem 1.5rem 1rem;
    text-align: center;
    border-bottom: 1px solid var(--line);
  }
  .brand {
    letter-spacing: 0.35em;
    text-transform: uppercase;
    font-size: 0.72rem;
    color: var(--accent);
    font-family: "Segoe UI", system-ui, sans-serif;
    font-weight: 600;
  }
  h1 {
    margin-top: 0.6rem;
    font-weight: 400;
    font-size: clamp(1.8rem, 4vw, 2.8rem);
    letter-spacing: 0.04em;
  }
  .tagline {
    margin-top: 0.5rem;
    color: var(--muted);
    font-style: italic;
    font-size: 1.05rem;
  }
  .hero-wrap {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 2rem 1rem 3rem;
    background:
      radial-gradient(ellipse 60% 50% at 50% 45%, #1a1c24 0%, var(--bg) 70%);
  }
  #coin-hero {
    width: min(420px, 92vw);
    height: min(420px, 92vw);
    display: block;
    border-radius: 8px;
  }
  .hero-caption {
    margin-top: 1.25rem;
    font-family: "Segoe UI", system-ui, sans-serif;
    font-size: 0.75rem;
    letter-spacing: 0.2em;
    text-transform: uppercase;
