  }
  .edition .buy:disabled,
  .edition .status-badge {
    margin-top: 0.85rem;
    width: 100%;
    font-family: "Segoe UI", system-ui, sans-serif;
    font-size: 0.72rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    padding: 0.65rem 0.5rem;
    text-align: center;
    border-radius: 2px;
  }
  .edition[data-state="sold-out"] .status-badge {
    background: #3a1e1e;
    color: #e07070;
    border: 1px solid #5a3030;
  }
  .edition[data-state="coming-soon"] .status-badge {
    background: #1e2430;
    color: #7a9cc0;
    border: 1px solid #2a3850;
  }
  footer {
    border-top: 1px solid var(--line);
    padding: 2rem 1.5rem;
    text-align: center;
    font-family: "Segoe UI", system-ui, sans-serif;
    font-size: 0.75rem;
    color: var(--muted);
    letter-spacing: 0.08em;
  }
  .toast {
    position: fixed;
    bottom: 1.5rem;
