<script>
(function () {
  "use strict";

  // ---------- Math helpers ----------
  function clamp(v, a, b) { return Math.max(a, Math.min(b, v)); }
  function lerp(a, b, t) { return a + (b - a) * t; }
  function smoothstep(e0, e1, x) {
    var t = clamp((x - e0) / (e1 - e0), 0, 1);
    return t * t * (3 - 2 * t);
  }

  // ---------- Coin renderer (2.5D projected disc with thickness) ----------
  // Deterministic pure-function style: given angles + metal, paint canvas.

  function metalPalette(kind) {
    switch (kind) {
      case "bronze":
        return {
          base: [184, 115, 51],
          dark: [90, 48, 18],
          mid: [160, 96, 42],
          light: [232, 180, 110],
          spec: [255, 236, 200],
          emboss: [120, 70, 30],
          ink: [60, 30, 10]
        };
      case "silver":
        return {
          base: [192, 198, 206],
          dark: [70, 76, 86],
          mid: [160, 168, 178],
          light: [235, 240, 248],
          spec: [255, 255, 255],
          emboss: [110, 118, 130],
          ink: [40, 44, 52]
        };
      case "gold":
        return {
          base: [212, 175, 55],
          dark: [100, 72, 12],
          mid: [190, 150, 40],
          light: [255, 226, 130],
          spec: [255, 250, 220],
          emboss: [150, 110, 25],
          ink: [70, 48, 8]
        };
      case "black":
        return {
          base: [36, 36, 42],
          dark: [8, 8, 10],
          mid: [48, 48, 56],
          light: [110, 114, 128],
          spec: [200, 210, 230],
          emboss: [22, 22, 28],
          ink: [180, 185, 200]
        };
      default: // hero default: rich antique gold-brass
        return {
          base: [198, 160, 72],
          dark: [78, 52, 14],
          mid: [170, 130, 48],
          light: [245, 215, 130],
          spec: [255, 248, 220],
          emboss: [130, 95, 28],
          ink: [55, 35, 8]
        };
    }
  }

  function rgb(c, a) {
    if (a == null || a >= 1) return "rgb(" + (c[0]|0) + "," + (c[1]|0) + "," + (c[2]|0) + ")";
    return "rgba(" + (c[0]|0) + "," + (c[1]|0) + "," + (c[2]|0) + "," + a + ")";
  }
  function mix(a, b, t) {
    return [
      a[0] + (b[0] - a[0]) * t,
      a[1] + (b[1] - a[1]) * t,
      a[2] + (b[2] - a[2]) * t
    ];
  }

  // Draw emblem / denomination onto an offscreen face buffer
  function buildFaceCanvas(size, face, pal, denomination) {
    var c = document.createElement("canvas");
    c.width = size;
    c.height = size;
    var g = c.getContext("2d");
    var cx = size / 2, cy = size / 2, R = size * 0.48;

    // Face disc base with subtle radial metal
    var grd = g.createRadialGradient(cx - R * 0.25, cy - R * 0.3, R * 0.1, cx, cy, R);
    grd.addColorStop(0, rgb(pal.light));
    grd.addColorStop(0.45, rgb(pal.mid));
    grd.addColorStop(1, rgb(pal.dark));
    g.fillStyle = grd;
    g.beginPath();
    g.arc(cx, cy, R, 0, Math.PI * 2);
    g.fill();

    // Concentric lathe rings
    g.save();
    g.beginPath();
    g.arc(cx, cy, R, 0, Math.PI * 2);
    g.clip();
    for (var i = 0; i < 28; i++) {
      var rr = R * (0.15 + i * 0.03);
      g.strokeStyle = rgb(i % 2 ? pal.dark : pal.light, 0.07);
      g.lineWidth = 1;
      g.beginPath();
      g.arc(cx, cy, rr, 0, Math.PI * 2);
      g.stroke();
    }

    // Outer raised rim
    g.lineWidth = size * 0.028;
    g.strokeStyle = rgb(pal.light, 0.55);
    g.beginPath();
    g.arc(cx, cy, R * 0.93, 0, Math.PI * 2);
    g.stroke();
    g.lineWidth = size * 0.012;
    g.strokeStyle = rgb(pal.dark, 0.5);
    g.beginPath();
    g.arc(cx, cy, R * 0.90, 0, Math.PI * 2);
    g.stroke();

    // Inner ring
    g.lineWidth = size * 0.01;
    g.strokeStyle = rgb(pal.ink, 0.35);
    g.beginPath();
    g.arc(cx, cy, R * 0.72, 0, Math.PI * 2);
    g.stroke();

    if (face === "front") {
      drawFrontEmblem(g, cx, cy, R, pal, size);
    } else {
      drawBackDenom(g, cx, cy, R, pal, size, denomination);
    }
    g.restore();
    return c;
  }

  function drawFrontEmblem(g, cx, cy, R, pal, size) {
    // Raised W / token emblem
    g.save();
    // Banner arc text
    g.font = "bold " + Math.floor(size * 0.055) + "px Georgia, serif";
    g.fillStyle = rgb(pal.ink, 0.85);
    g.textAlign = "center";
    g.textBaseline = "middle";
    drawCircularText(g, "WASTEDTOKEN MINT", cx, cy, R * 0.82, -Math.PI * 0.72, Math.PI * 0.72, false);
    drawCircularText(g, "EST. MMXXIV · PROOF OF WASTE", cx, cy, R * 0.82, Math.PI * 0.78, Math.PI * 2.22, true);

    // Central shield / coin mark
    var s = R * 0.42;
    // Outer hex
    g.beginPath();
    for (var i = 0; i < 6; i++) {
      var a = -Math.PI / 2 + i * Math.PI / 3;
      var x = cx + Math.cos(a) * s;
      var y = cy + Math.sin(a) * s * 0.95;
      if (i === 0) g.moveTo(x, y); else g.lineTo(x, y);
    }
    g.closePath();
    // Raised bevel fill
    var hg = g.createLinearGradient(cx - s, cy - s, cx + s, cy + s);
    hg.addColorStop(0, rgb(pal.light, 0.95));
    hg.addColorStop(0.4, rgb(pal.mid));
    hg.addColorStop(1, rgb(pal.dark));
    g.fillStyle = hg;
    g.fill();
    g.lineWidth = size * 0.012;
    g.strokeStyle = rgb(pal.ink, 0.55);
    g.stroke();

    // Inner circle
    g.beginPath();
    g.arc(cx, cy, s * 0.62, 0, Math.PI * 2);
    g.fillStyle = rgb(pal.dark, 0.35);
    g.fill();
    g.strokeStyle = rgb(pal.light, 0.4);
    g.lineWidth = size * 0.008;
    g.stroke();

    // Big W monogram (embossed)
    g.font = "bold " + Math.floor(size * 0.28) + "px Georgia, serif";
    g.textAlign = "center";
    g.textBaseline = "middle";
    // shadow (recessed)
    g.fillStyle = rgb(pal.dark, 0.7);
    g.fillText("W", cx + 1.5, cy + 2);
    // highlight lip
    g.fillStyle = rgb(pal.light, 0.95);
    g.fillText("W", cx - 1, cy - 1.5);
    // body
    g.fillStyle = rgb(pal.ink, 0.9);
    g.fillText("W", cx, cy);

    // Small stars
    g.fillStyle = rgb(pal.ink, 0.7);
    drawStar(g, cx - s * 0.95, cy, size * 0.018);
    drawStar(g, cx + s * 0.95, cy, size * 0.018);

    g.restore();
  }

  function drawBackDenom(g, cx, cy, R, pal, size, denomination) {
    g.save();
    g.font = "bold " + Math.floor(size * 0.048) + "px Georgia, serif";
    g.fillStyle = rgb(pal.ink, 0.8);
    g.textAlign = "center";
    g.textBaseline = "middle";
    drawCircularText(g, "CHALLENGE COIN · REDEEMABLE FOR NOTHING", cx, cy, R * 0.82, -Math.PI * 0.85, Math.PI * 0.85, false);

    // Denomination block
    var lines = String(denomination).split("\n");
    g.font = "bold " + Math.floor(size * 0.13) + "px Georgia, serif";
    // embossed number
    var ty = cx; // center-ish
    var totalH = lines.length * size * 0.14;
    var startY = cy - totalH * 0.25;

    for (var i = 0; i < lines.length; i++) {
      var y = startY + i * size * 0.145;
      g.fillStyle = rgb(pal.dark, 0.65);
      g.fillText(lines[i], cx + 1.5, y + 2);
      g.fillStyle = rgb(pal.light, 0.9);
      g.fillText(lines[i], cx - 1, y - 1.2);
      g.fillStyle = rgb(pal.ink, 0.92);
      g.fillText(lines[i], cx, y);
    }

    // Small seal
    g.beginPath();
    g.arc(cx, cy + R * 0.42, R * 0.1, 0, Math.PI * 2);
    g.strokeStyle = rgb(pal.ink, 0.5);
    g.lineWidth = size * 0.006;
    g.stroke();
    g.font = "bold " + Math.floor(size * 0.04) + "px Georgia, serif";
    g.fillStyle = rgb(pal.ink, 0.75);
    g.fillText("WT", cx, cy + R * 0.42);

    g.restore();
  }

  function drawCircularText(g, text, cx, cy, radius, startAngle, endAngle, clockwise) {
    var chars = text.split("");
    var span = endAngle - startAngle;
    if (clockwise) {
      // bottom arc, reverse visual order
      var ang = startAngle;
      var step = span / chars.length;
      for (var i = 0; i < chars.length; i++) {
        var a = ang + step * (i + 0.5);
        g.save();
        g.translate(cx + Math.cos(a) * radius, cy + Math.sin(a) * radius);
        g.rotate(a + Math.PI / 2);
        g.fillText(chars[i], 0, 0);
        g.restore();
      }
    } else {
      var step2 = span / chars.length;
      for (var j = 0; j < chars.length; j++) {
        var a2 = startAngle + step2 * (j + 0.5);
        g.save();
        g.translate(cx + Math.cos(a2) * radius, cy + Math.sin(a2) * radius);
        g.rotate(a2 + Math.PI / 2);
        g.fillText(chars[j], 0, 0);
        g.restore();
      }
    }
  }

  function drawStar(g, x, y, r) {
    g.beginPath();
    for (var i = 0; i < 5; i++) {
      var a = -Math.PI / 2 + i * Math.PI * 2 / 5;
      var a2 = a + Math.PI / 5;
      var px = x + Math.cos(a) * r;
      var py = y + Math.sin(a) * r;
      if (i === 0) g.moveTo(px, py); else g.lineTo(px, py);
      g.lineTo(x + Math.cos(a2) * r * 0.4, y + Math.sin(a2) * r * 0.4);
    }
    g.closePath();
    g.fill();
  }

  // Cache face textures per metal+face+denom
  var faceCache = {};
  function getFaces(kind, denom, size) {
    var key = kind + "|" + denom + "|" + size;
    if (faceCache[key]) return faceCache[key];
    var pal = metalPalette(kind);
    var front = buildFaceCanvas(size, "front", pal, denom);
    var back = buildFaceCanvas(size, "back", pal, denom);
    faceCache[key] = { front: front, back: back, pal: pal };
    return faceCache[key];
  }

  /**
   * Render coin at rotation angles.
   * rotY: spin about vertical (radians)
   * rotX: flip about horizontal (radians)
   */
  function renderCoin(ctx, w, h, rotY, rotX, kind, denomination, opts) {
    opts = opts || {};
    var pal = metalPalette(kind);
    var cx = w / 2;
    var cy = h / 2;
    var radius = Math.min(w, h) * (opts.radiusScale != null ? opts.radiusScale : 0.32);
    var thickness = radius * 0.14;

    // Backdrop — simple, solid-ish
    ctx.clearRect(0, 0, w, h);
    if (!opts.noBg) {
      var bg = ctx.createRadialGradient(cx, cy, radius * 0.2, cx, cy, Math.max(w, h) * 0.65);
      bg.addColorStop(0, "#14161c");
      bg.addColorStop(1, "#0a0b0e");
      ctx.fillStyle = bg;
      ctx.fillRect(0, 0, w, h);
    }

    // 3D orientation: start with disc in XY plane, normal +Z.
    // Apply rotX (pitch) then rotY (yaw).
    var cosY = Math.cos(rotY), sinY = Math.sin(rotY);
    var cosX = Math.cos(rotX), sinX = Math.sin(rotX);

    // Basis vectors after rotation
    // Local +X (right on coin)
    var xx = cosY;
    var xy = sinY * sinX;
